// npm run seed:bundle — builds the seed-kitchen function's generated files:
//   _domain.js       the app's recipe rules (src/domain), bundled
//   _ingredients.js  the app's ingredient database, trimmed to id, name, aliases and groups
// Both are generated: change src/ and re-run this, never edit them by hand.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

const out = 'supabase/functions/seed-kitchen';
execFileSync('npx', ['-y', 'esbuild@0.28.2', 'scripts/seed/domain-entry.ts', '--bundle', '--format=esm',
  '--platform=neutral', '--minify', '--legal-comments=none',
  '--banner:js=// Generated by npm run seed:bundle from src/domain. Do not edit.', `--outfile=${out}/_domain.js`], { stdio: 'inherit' });

const defs = JSON.parse(readFileSync('src/data/ingredients/ingredients.json', 'utf8'));
const rows = defs.map((d) => [d.id, d.name, d.aliases, d.groups]);
// One row per line keeps the file readable in diffs.
const body = rows.map((r) => JSON.stringify(r)).join(',\n');
writeFileSync(`${out}/_ingredients.js`,
  `// Generated by npm run seed:bundle from src/data/ingredients/ingredients.json. Do not edit.\n` +
  `/** @type {[string, string, string[], string[]][]} */\nconst rows = [\n${body}\n];\n` +
  `/** @type {{ id: string; name: string; aisle: string; aliases: string[]; groups: string[] }[]} */\n` +
  `export const INGREDIENTS = rows.map(([id, name, aliases, groups]) => ({ id, name, aisle: 'other', aliases, groups }));\n`);
console.log(`${rows.length} ingredients`);
